import {OSA_QUESTIONS,OSA_FIRST_AID,OSA_SITES,osaStageText,osaVitalText} from './osa-bleeding.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,value='',disabled=false)=>`<button class="fish-button" data-osa-action="${action}" data-osa-value="${value}" ${disabled?'disabled':''}>${label}</button>`;
export function osaPhoneHTML(t){return`<span class="modal-tag urgent">☎ 病房急call</span><h2 id="modalTitle">醫師，${t.patient.bed}在吐血！</h2><div class="dialogue">主護：「${t.patient.bed}，${esc(t.patient.name)}，五天前開達文西OSA，現在在吐血。」</div>${OSA_QUESTIONS.map(q=>btn((t.asked.includes(q.id)?'✓ ':'')+q.text,'ask',q.id,t.asked.includes(q.id))+(t.asked.includes(q.id)?'<p class="modal-copy">主護：「'+esc(q.id==='amount'?t.amount:osaVitalText(t))+'」</p>':'')).join('')}<h3>先交代床邊處理</h3>${OSA_FIRST_AID.map(q=>btn((t.firstAid.includes(q.id)?'✓ ':'')+q.text,'first-aid',q.id,t.asked.length<2||t.firstAid.includes(q.id))).join('')}<div class="osa-route">${btn('我現在直接到床邊','route','direct',t.firstAid.length<2)}${btn('我先下2G拿fiber，馬上到床邊','route','fiber',t.firstAid.length<2)}</div><p id="osaFeedback" class="fish-feedback" role="status"></p><button id="osaLater" class="text-button">保留來電，稍後回覆</button>`;}
function view(t,fiber=false){const visible=fiber||t.examined&&t.clearWithHeadlamp,base=t.site==='tongue',blood=visible?base?'<ellipse cx="250" cy="218" rx="17" ry="11" fill="#b4454c"/><path d="M250 224l7 16" stroke="#b4454c" stroke-width="4"/>':'<ellipse cx="326" cy="146" rx="13" ry="19" fill="#b4454c"/><path d="M326 162l-2 22" stroke="#b4454c" stroke-width="4"/>':t.examined?'<path d="M150 165Q235 126 329 174L310 209Q235 180 170 205Z" fill="#805254" opacity=".8"/>':'';return`<div class="fish-view ${!fiber&&!t.headlamp?'fish-unlit':''}"><svg viewBox="0 0 480 310" role="img" aria-label="${fiber?'Fiber':'頭燈'}下的口腔與舌根簡化視野"><defs><radialGradient id="osaMucosa"><stop stop-color="#bd8f83"/><stop offset="1" stop-color="#342b35"/></radialGradient></defs><rect width="480" height="310" fill="#1c3039"/><ellipse cx="240" cy="157" rx="203" ry="132" fill="url(#osaMucosa)"/><path d="M140 89Q240 52 340 89M140 89q-45 68 0 134M340 89q45 68 0 134" fill="none" stroke="#d2a092" stroke-width="17"/><ellipse cx="156" cy="148" rx="25" ry="42" fill="#a56c6e"/><ellipse cx="324" cy="148" rx="25" ry="42" fill="#a56c6e"/><path d="M165 226Q240 124 315 226Q240 272 165 226Z" fill="#bc8380"/><path d="M215 81q25 42 50 0" fill="#d3a593"/>${blood}<text x="20" y="24" fill="#cbd9cd" font-size="12">${fiber?'FIBER':'HEADLAMP'} / POST-OP VIEW</text><text x="240" y="295" text-anchor="middle" fill="#bbc9be" font-size="11">簡化遊戲視野</text></svg></div>`;}
export function osaHTML(t,message=''){
 let body='';const s=t.stage==='handoff'&&!t.reported?'recheck':t.stage;
 if(s==='pickup')body='<div class="osa-equipment"><span aria-hidden="true">◉</span><b>Fiber與攜帶盒</b><p>把內視鏡備好，回7F23A床邊。</p></div>'+btn('拿起fiber，回病房 →','pickup');
 if(s==='arrival')body='<div class="dialogue">主護：「已經讓病人坐高、口含冰水，目前仍有血水。」</div>'+btn('到床邊，重新看病人與vital signs','arrival');
 if(s==='headlamp')body=`<div class="fish-layout">${view(t)}<div class="fish-work">${btn(t.headlamp?'✓ 頭燈已戴好':'戴上頭燈','headlamp','',t.headlamp)}${btn(t.examined?'✓ 口腔已檢查':'用頭燈看嘴巴','examine','',!t.headlamp||t.examined)}${t.examined?'<p>'+ (t.clearWithHeadlamp?'頭燈下可見一側扁桃腺附近出血。':'目前口腔視野看不清楚出血點，需接續fiber確認。')+'</p>':''}${t.examined&&t.clearWithHeadlamp?OSA_SITES.map(p=>btn('出血點在'+p.name,'identify',p.id)).join(''):''}${t.examined&&!t.clearWithHeadlamp&&!t.hasFiber?btn('請同事送fiber到床邊','request-fiber'):''}${t.examined&&!t.clearWithHeadlamp?btn('用fiber接續確認 →','fiber','',!t.hasFiber):''}</div></div>`;
 if(s==='scope')body=`<div class="fish-layout">${view(t,true)}<div class="fish-work"><p>檢查所見的紅色出血點在哪裡？</p>${OSA_SITES.map(p=>btn(p.name,'identify',p.id)).join('')}</div></div>`;
 if(s==='packing')body=`<section class="fish-case-note"><b>出血點：${OSA_SITES.find(p=>p.id===t.site).name}</b><p>先做床邊止血，再看反應。</p></section>${btn('用Bosmin紗布止血','bosmin')}`;
 if(s==='medical')body=`<p class="modal-copy">已完成Bosmin紗布止血，接續處置並留意反應。</p><div class="dialogue">${osaVitalText(t)}</div>${btn(t.treated.includes('transamin')?'✓ Transamin已安排':'安排Transamin處置','medical','transamin',t.treated.includes('transamin'))}${btn(t.treated.includes('bp')?'✓ 血壓已評估處理':t.bpHigh?'評估並處理偏高血壓':'評估血壓，持續監測','medical','bp',t.treated.includes('bp'))}${t.treated.length===3?'<p class="modal-copy">出血已控制，接著向二線學長報告。</p>':''}${btn('打給二線學長報告 →','report-senior','',t.treated.length<3)}`;
 if(s==='recheck')body='<p class="modal-copy">出血已控制。</p>'+btn('打給二線學長報告 →','report-senior');
 if(s==='handoff')body='<div class="dialogue">二線學長：「了解，繼續觀察，有狀況再打給我。」</div>'+btn('向主護交代持續觀察、再出血回報，結束 ✓','finish');
 return`<span class="modal-tag urgent">${s==='pickup'?'2G · 拿fiber':'7F 病房 · 床邊處理'}</span><h2 id="modalTitle">${osaStageText(t)}</h2><p class="fish-patient"><b>${t.patient.bed} · ${esc(t.patient.name)}</b><span>達文西OSA術後第5天</span></p>${body}<p id="osaFeedback" class="fish-feedback" role="status">${esc(message)}</p><footer class="fish-footer"><small>科內娛樂的簡化情境</small><button id="osaLater" class="text-button">先離開，進度保留 →</button></footer>`;
}
export function bindOSA({act,later}){document.querySelectorAll('[data-osa-action]').forEach(b=>b.onclick=()=>act(b.dataset.osaAction,b.dataset.osaValue));document.getElementById('osaLater').onclick=later;}
